#ifndef PW_SHELL_CURSORS_H
#define PW_SHELL_CURSORS_H
#include <windows.h>
#include "pw_cursor_scheme.h"  /* generated by tools/build-cursors.py from themes/windows11/cursors/manifest.json */
/* The Mihawk pointer scheme, named once per prefix by the session root (Wine patch 1138) the way Windows' default
 * scheme is: one REG_EXPAND_SZ per role in HKCU\Control Panel\Cursors, read by user32 for every system cursor (patch
 * 1137). The files are the runtime's C:\windows\Cursors (tools/stage-wine.py). A scheme already chosen (any role has a
 * value) is kept; a runtime without the files leaves Wine's own cursors and is tried again next session.
 * tests/cursor-scheme-probe.c runs this very function against the real registry. */
static DWORD pw_shell_prepare_cursors(void)
{
    static const struct { const WCHAR *role, *file; } scheme[] = PW_CURSOR_SCHEME;
    HKEY settings = NULL, cursors = NULL;
    DWORD initialized = 0, size = sizeof(initialized), type = 0, status;
    WCHAR path[MAX_PATH], value[MAX_PATH];
    UINT i, length, chosen = 0;

    status = RegCreateKeyExW(HKEY_CURRENT_USER, L"Software\\MihawkOS", 0, NULL, 0,
                             KEY_QUERY_VALUE | KEY_SET_VALUE, NULL, &settings, NULL);
    if (status != ERROR_SUCCESS) return status;
    if (RegQueryValueExW(settings, L"CursorsInitialized", NULL, &type, (BYTE *)&initialized, &size) == ERROR_SUCCESS &&
        type == REG_DWORD && size == sizeof(initialized) && initialized == 1)
    { RegCloseKey(settings); return ERROR_SUCCESS; }
    for (i = 0; i < sizeof(scheme) / sizeof(scheme[0]); i++)
    {
        length = GetWindowsDirectoryW(path, MAX_PATH);
        if (!length || length + 10 + lstrlenW(scheme[i].file) >= MAX_PATH) { RegCloseKey(settings); return ERROR_INSUFFICIENT_BUFFER; }
        lstrcatW(path, L"\\Cursors\\");
        lstrcatW(path, scheme[i].file);
        if (GetFileAttributesW(path) == INVALID_FILE_ATTRIBUTES) { RegCloseKey(settings); return ERROR_SUCCESS; }
    }
    status = RegCreateKeyExW(HKEY_CURRENT_USER, L"Control Panel\\Cursors", 0, NULL, 0,
                             KEY_QUERY_VALUE | KEY_SET_VALUE, NULL, &cursors, NULL);
    if (status == ERROR_SUCCESS)
    {
        for (i = 0; i < sizeof(scheme) / sizeof(scheme[0]); i++)
            if (RegQueryValueExW(cursors, scheme[i].role, NULL, NULL, NULL, NULL) == ERROR_SUCCESS) chosen++;
        for (i = 0; !chosen && status == ERROR_SUCCESS && i < sizeof(scheme) / sizeof(scheme[0]); i++)
        {
            lstrcpyW(value, L"%SystemRoot%\\Cursors\\");
            lstrcatW(value, scheme[i].file);
            status = RegSetValueExW(cursors, scheme[i].role, 0, REG_EXPAND_SZ, (BYTE *)value,
                                    (lstrlenW(value) + 1) * sizeof(WCHAR));
        }
        if (!chosen && status == ERROR_SUCCESS)
            status = RegSetValueExW(cursors, NULL, 0, REG_SZ, (BYTE *)PW_CURSOR_SCHEME_NAME,
                                    sizeof(PW_CURSOR_SCHEME_NAME));
        RegCloseKey(cursors);
    }
    if (status == ERROR_SUCCESS)
    {
        initialized = 1;
        status = RegSetValueExW(settings, L"CursorsInitialized", 0, REG_DWORD, (BYTE *)&initialized, sizeof(initialized));
    }
    RegCloseKey(settings);
    return status;
}
#endif
